import 'package:flutter/material.dart';
import '../models/playlist_item.dart';
import '../services/m3u_parser_service.dart';

class AddPlaylistScreen extends StatefulWidget {
  const AddPlaylistScreen({super.key});

    @override
      State<AddPlaylistScreen> createState() => _AddPlaylistScreenState();
      }

      class _AddPlaylistScreenState extends State<AddPlaylistScreen> {
        final _urlController = TextEditingController();
          bool _isLoading = false;
            String? _errorMessage;

              void _processPlaylist() async {
                  final url = _urlController.text.trim();
                      if (url.isEmpty) return;

                          setState(() {
                                _isLoading = true;
                                      _errorMessage = null;
                                          });

                                              try {
                                                    List<PlaylistItem> items = await M3UParserService.fetchAndParseM3U(url);
                                                          if (mounted) {
                                                                  Navigator.pop(context, items);
                                                                        }
                                                                            } catch (e) {
                                                                                  setState(() {
                                                                                          _errorMessage = 'Error al cargar o procesar la lista M3U. Verifica la URL.';
                                                                                                });
                                                                                                    } finally {
                                                                                                          if (mounted) {
                                                                                                                  setState(() {
                                                                                                                            _isLoading = false;
                                                                                                                                    });
                                                                                                                                          }
                                                                                                                                              }
                                                                                                                                                }

                                                                                                                                                  @override
                                                                                                                                                    Widget build(BuildContext context) {
                                                                                                                                                        return Scaffold(
                                                                                                                                                              backgroundColor: const Color(0xFF121212),
                                                                                                                                                                    appBar: AppBar(
                                                                                                                                                                            title: const Text('Cargar Lista M3U / AI Clean'),
                                                                                                                                                                                    backgroundColor: Colors.transparent,
                                                                                                                                                                                          ),
                                                                                                                                                                                                body: Padding(
                                                                                                                                                                                                        padding: const EdgeInsets.all(24.0),
                                                                                                                                                                                                                child: Column(
                                                                                                                                                                                                                          mainAxisAlignment: MainAxisAlignment.center,
                                                                                                                                                                                                                                    crossAxisAlignment: CrossAxisAlignment.stretch,
                                                                                                                                                                                                                                              children: [
                                                                                                                                                                                                                                                          const Icon(Icons.psychology_outlined, size: 70, color: Colors.deepPurpleAccent),
                                                                                                                                                                                                                                                                      const SizedBox(height: 16),
                                                                                                                                                                                                                                                                                  const Text(
                                                                                                                                                                                                                                                                                                'Ingresa tu lista M3U',
                                                                                                                                                                                                                                                                                                              style: TextStyle(color: Colors.white, fontSize: 22, fontWeight: FontWeight.bold),
                                                                                                                                                                                                                                                                                                                            textAlign: TextAlign.center,
                                                                                                                                                                                                                                                                                                                                        ),
                                                                                                                                                                                                                                                                                                                                                    const SizedBox(height: 8),
                                                                                                                                                                                                                                                                                                                                                                const Text(
                                                                                                                                                                                                                                                                                                                                                                              'Nuestro motor de IA limpiará los nombres de los canales y ordenará las categorías automáticamente.',
                                                                                                                                                                                                                                                                                                                                                                                            style: TextStyle(color: Colors.grey, fontSize: 13),
                                                                                                                                                                                                                                                                                                                                                                                                          textAlign: TextAlign.center,
                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                  const SizedBox(height: 30),
                                                                                                                                                                                                                                                                                                                                                                                                                                              TextField(
                                                                                                                                                                                                                                                                                                                                                                                                                                                            controller: _urlController,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          style: const TextStyle(color: Colors.white),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        decoration: InputDecoration(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        hintText: 'https://ejemplo.com/lista.m3u',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        hintStyle: const TextStyle(color: Colors.white38),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        filled: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        fillColor: const Color(0xFF1E1E2E),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        border: OutlineInputBorder(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          borderRadius: BorderRadius.circular(12),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            borderSide: BorderSide.none,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            prefixIcon: const Icon(Icons.link, color: Colors.deepPurpleAccent),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (_errorMessage != null) ...[
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const SizedBox(height: 12),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Text(_errorMessage!, style: const TextStyle(color: Colors.redAccent, fontSize: 12)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const SizedBox(height: 24),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ElevatedButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onPressed: _isLoading ? null : _processPlaylist,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              style: ElevatedButton.styleFrom(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              backgroundColor: Colors.deepPurpleAccent,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              padding: const EdgeInsets.symmetric(vertical: 16),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          child: _isLoading
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ? const CircularProgressIndicator(color: Colors.white)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              : const Text('Procesar y Sanitizar con IA', style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold, color: Colors.white)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        